const ZH=LANG==='zh'&&typeof ZH_KO!=='undefined'?ZH_KO:null;
function _T(s){if(ZH&&ZH[s]!=null)return ZH[s];return EN&&EN[s]!=null?EN[s]:s}
// Chinese for _L(ko,en): exact English match, then English templates with {n} slots for runtime values, then the Korean key.
let ZHT=null;const ZHC=new Map();
function zhL(ko,en){if(typeof en!=='string')return en;let r=ZH_EN[en];if(r!=null)return r;r=ZHC.get(en);if(r!=null)return r;
  if(!ZHT){ZHT=[];for(const k in ZH_EN){if(k.indexOf('{')<0)continue;const lit=k.replace(/\{\d+\}/g,'');if(lit.replace(/[^A-Za-z]/g,'').length<3)continue;ZHT.push([new RegExp('^'+k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\\\{(\d+)\\\}/g,'(?<p$1>[\\s\\S]*?)')+'$'),ZH_EN[k],lit.length]);}ZHT.sort((a,b)=>b[2]-a[2]);}
  r=null;for(const [re,z] of ZHT){const m=re.exec(en);if(m){r=z.replace(/\{(\d+)\}/g,(_,n)=>m.groups['p'+n]);break;}}
  if(r==null)r=typeof ko!=='string'?en:ZH[ko]!=null?ZH[ko]:/[\u4e00-\u9fff]/.test(ko)&&!/[\uac00-\ud7a3]/.test(ko)?ko:en;if(ZHC.size>3000)ZHC.clear();ZHC.set(en,r);return r;}
function _L(ko,en){return LANG==='ko'?ko:LANG==='zh'&&ZH?zhL(ko,en):en}
function langMenu(btn){let m=document.getElementById('langMenu');if(m){m.remove();return;}m=document.createElement('div');m.id='langMenu';m.setAttribute('role','menu');
  m.innerHTML=LANGS.map(([k,n])=>'<button type="button" role="menuitemradio" aria-checked="'+(k===LANG)+'" data-l="'+k+'">'+(k===LANG?'✓ ':'')+n+'</button>').join('');
  const r=btn.getBoundingClientRect();m.style.left=Math.max(8,Math.min(window.innerWidth-170,r.left))+'px';m.style.top=(r.bottom+6+170>window.innerHeight?r.top-6-LANGS.length*40:r.bottom+6)+'px';document.body.appendChild(m);
  m.addEventListener('click',e=>{const k=e.target.closest('[data-l]');if(!k)return;const v=k.dataset.l;m.remove();if(v===LANG)return;try{if(running&&S&&!NC()&&S.phase==='day'&&!S.tower)save();}catch(_){}try{localStorage.setItem('cs-lang-v1',v);}catch(_){}location.reload();});
  setTimeout(()=>document.addEventListener('pointerdown',function f(e){if(!m.contains(e.target)&&e.target!==btn){m.remove();document.removeEventListener('pointerdown',f);}}),0);}
function i18nDom(){document.documentElement.lang=LANG==='zh'?'zh-CN':LANG;for(const b of document.querySelectorAll('[data-lang-toggle]')){b.querySelector('.lnext').textContent=(LANGS.find(l=>l[0]===LANG)||LANGS[0])[1];b.setAttribute('aria-haspopup','menu');b.addEventListener('click',()=>langMenu(b));}if(!EN)return;const D=ZH||EN,tr=k=>D[k]!=null?D[k]:EN[k];const tw=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const ns=[];while(tw.nextNode())ns.push(tw.currentNode);
  for(const n of ns){const t=n.nodeValue,k=t.trim();if(k&&tr(k)!=null&&!(n.parentNode&&/^(SCRIPT|STYLE)$/.test(n.parentNode.nodeName)))n.nodeValue=t.replace(k,tr(k));}
  for(const el of document.querySelectorAll('[aria-label],[title],[placeholder]'))for(const a of ['aria-label','title','placeholder']){const v=el.getAttribute(a);if(v&&tr(v)!=null)el.setAttribute(a,tr(v));}
  if(tr(document.title)!=null)document.title=tr(document.title);}
